package com.greenocean.backend;
import com.greenocean.backend.professional.service.*;import com.greenocean.backend.common.exception.*;
import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.test.context.ActiveProfiles;import org.springframework.transaction.annotation.Transactional;import org.junit.jupiter.api.*;import org.springframework.mock.web.MockMultipartFile;
import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.*;
@SpringBootTest(properties={"greenocean.clinic.commerce-enabled=true","greenocean.clinic.records-enabled=true","greenocean.clinic.record-keys=clinical-qa:AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=","greenocean.clinic.record-current-key=clinical-qa"}) @AutoConfigureMockMvc @ActiveProfiles("test") @Transactional
class PhaseP3Test extends PhaseP3Fixtures {
 @Test void exactNoticesAndBothExplicitEntriesAreRequired(){assertThatThrownBy(()->care.enter(learner.id(),learner.session(),appointment)).isInstanceOf(ConflictException.class);consent();UUID id=care.enter(learner.id(),learner.session(),appointment);assertThatThrownBy(()->care.start(author.id(),author.session(),id,1)).isInstanceOfAny(ConflictException.class,ForbiddenException.class);care.enter(author.id(),author.session(),appointment);care.start(author.id(),author.session(),id,1);assertThat(care.status(learner.id(),learner.session(),id).get("state")).isEqualTo("ACTIVE");}
 @Test void clinicalMessageCipherIsNotSocialMessageAndRetryIsOnce(){UUID id=active(),retry=UUID.randomUUID(),message=care.message(learner.id(),learner.session(),id,retry,"Private synthetic clinical wording");assertThat(care.message(learner.id(),learner.session(),id,retry,"Private synthetic clinical wording")).isEqualTo(message);assertThat(care.messages(author.id(),author.session(),id,0).toString()).contains("Private synthetic clinical wording");byte[] cipher=db.queryForObject("SELECT body_cipher FROM clinic_messages WHERE id=?",byte[].class,message);assertThat(new String(cipher,java.nio.charset.StandardCharsets.UTF_8)).doesNotContain("Private synthetic");assertThat(db.queryForObject("SELECT count(*) FROM messages WHERE body LIKE '%Private synthetic clinical wording%'",Integer.class)).isZero();}
 @Test void adminFinanceModeratorAndOtherPatientCannotReadClinicalText(){UUID id=active();care.message(learner.id(),learner.session(),id,UUID.randomUUID(),"Private synthetic record");assertThatThrownBy(()->care.messages(issuer.id(),issuer.session(),id,0)).isInstanceOf(ForbiddenException.class);assertThatThrownBy(()->care.messages(other.id(),other.session(),id,0)).isInstanceOf(ForbiddenException.class);}
 @Test void finalizedNotesCanOnlyReceiveAnExplicitImmutableAmendment(){UUID id=active(),retry=UUID.randomUUID();var initial=new ClinicalCare.Note(null,0,"SHARED_NOTES","FINAL","Synthetic final clinical note",retry);UUID note=care.note(author.id(),author.session(),id,initial);assertThat(care.note(author.id(),author.session(),id,initial)).isEqualTo(note);assertThatThrownBy(()->care.note(author.id(),author.session(),id,new ClinicalCare.Note(note,1,"SHARED_NOTES","DRAFT","Attempt to replace final note",UUID.randomUUID()))).isInstanceOf(ConflictException.class);care.note(author.id(),author.session(),id,new ClinicalCare.Note(note,1,"SHARED_NOTES","AMENDMENT","Synthetic explicit correction retained with original",UUID.randomUUID()));assertThat(care.notes(learner.id(),learner.session(),id,"SHARED_NOTES")).hasSize(2);assertThatThrownBy(()->care.notes(learner.id(),learner.session(),id,"PROFESSIONAL_NOTES")).isInstanceOf(ForbiddenException.class);}
 @Test void stoppedEncounterCannotSendMessagesOrBecomeCompletedByOneParty(){UUID id=active();care.message(learner.id(),learner.session(),id,UUID.randomUUID(),"Synthetic patient participation");care.message(author.id(),author.session(),id,UUID.randomUUID(),"Synthetic professional participation");care.stop(learner.id(),learner.session(),id,"PARTICIPANT_ENDED");assertThatThrownBy(()->care.message(learner.id(),learner.session(),id,UUID.randomUUID(),"Outside ended encounter")).isInstanceOf(ConflictException.class);care.acknowledge(author.id(),author.session(),id);assertThat(db.queryForObject("SELECT status FROM consultation_requests WHERE id=?",String.class,appointment)).isEqualTo("SESSION_ACTIVE");care.acknowledge(learner.id(),learner.session(),id);assertThat(db.queryForObject("SELECT status FROM consultation_requests WHERE id=?",String.class,appointment)).isEqualTo("COMPLETED");}
 @Test void consentWithdrawalStopsNewProcessing(){UUID id=active();var notice=care.notices(learner.id(),learner.session(),appointment,"en").getFirst();care.consent(learner.id(),learner.session(),appointment,(UUID)notice.get("id"),UUID.randomUUID(),"WITHDRAW");assertThat(care.status(learner.id(),learner.session(),id).get("state")).isEqualTo("ENDED");assertThatThrownBy(()->care.message(author.id(),author.session(),id,UUID.randomUUID(),"No consent means no processing")).isInstanceOf(ForbiddenException.class);}
 @Test void qualificationRevocationStopsProfessionalRecordAccess(){UUID id=active();db.update("UPDATE professional_verifications SET qualification_state='REVOKED' WHERE professional_user_id=?",author.id());assertThatThrownBy(()->care.messages(author.id(),author.session(),id,0)).isInstanceOf(ForbiddenException.class);assertThat(care.messages(learner.id(),learner.session(),id,0)).isEmpty();}
 @Test void revokedSessionCannotReadOrWrite(){UUID id=active();db.update("UPDATE user_sessions SET revoked_at=CURRENT_TIMESTAMP WHERE id=?",learner.session());assertThatThrownBy(()->care.messages(learner.id(),learner.session(),id,0)).isInstanceOf(UnauthorizedException.class);}
 @Test void wrongEnvelopePurposeAndKeyCannotRevealClinicalContent(){byte[] encrypted=care.seal("Private synthetic","encounter-one");assertThatThrownBy(()->care.open(encrypted,"encounter-two")).isInstanceOf(IllegalStateException.class);}
 @Test void attachmentsStayQuarantinedWhenScannerUnavailable(){UUID id=active();UUID file=files.upload(learner.id(),learner.session(),id,null,new MockMultipartFile("file","private.pdf","application/pdf","%PDF-1.4\nPrivate synthetic medical file".getBytes()));assertThat(files.list(learner.id(),learner.session(),id).getFirst().get("scan_state")).isEqualTo("PENDING");assertThatThrownBy(()->files.download(learner.id(),learner.session(),id,file)).isInstanceOf(ForbiddenException.class);assertThatThrownBy(()->files.upload(other.id(),other.session(),id,null,new MockMultipartFile("file","bad.pdf","application/pdf","not a pdf".getBytes()))).isInstanceOf(NotFoundException.class);}
 @Test void exceptionalRecordsAccessRequiresIndependentRolePurposeAndExpiry(){UUID id=active();role(issuer.id(),"CLINICAL_RECORDS_OPERATOR");role(reviewer.id(),"CLINICAL_RECORDS_OPERATOR");UUID request=care.requestAccess(issuer.id(),issuer.session(),id,"MESSAGES","Synthetic independently authorized subject-access case",Instant.now().plusSeconds(300));assertThatThrownBy(()->care.approveAccess(issuer.id(),issuer.session(),request)).isInstanceOf(ForbiddenException.class);UUID grant=care.approveAccess(reviewer.id(),reviewer.session(),request);assertThat(care.messages(issuer.id(),issuer.session(),id,0)).isEmpty();care.revokeAccess(reviewer.id(),reviewer.session(),grant);assertThatThrownBy(()->care.messages(issuer.id(),issuer.session(),id,0)).isInstanceOf(ForbiddenException.class);}
 @Test void textEncounterCannotMintMediaTokenOrEnableRecording(){UUID id=active();assertThatThrownBy(()->care.admission(learner.id(),learner.session(),id)).isInstanceOf(ConflictException.class);assertThat(care.status(learner.id(),learner.session(),id)).containsEntry("recordingEnabled",false).containsEntry("prescribingEnabled",false);}
 @Test void consentCannotBeSelfReviewed(){UUID draft=care.draftNotice(issuer.id(),new ClinicalCare.Notice("CARE_CONSENT","self-"+UUID.randomUUID(),"fa","TEXT","Synthetic independent notice required, not a real notice",Instant.now().minusSeconds(30),Instant.now().plusSeconds(300)));assertThatThrownBy(()->care.approveNotice(issuer.id(),draft,1)).isInstanceOf(ForbiddenException.class);}
 @Test void cancellationAfterExplicitEntryCannotBeRevivedByStartingEncounter(){UUID id=enter();commerce.change(learner.id(),appointment,new ClinicCommerce.Change(1,"CANCEL","Synthetic cancellation after entry before start"));assertThatThrownBy(()->care.start(author.id(),author.session(),id,1)).isInstanceOf(ConflictException.class);}
 @Test void directExportRequiresFreshPatientAuthenticationAndIncludesExplicitReviewBoundaries(){UUID id=active();care.message(learner.id(),learner.session(),id,UUID.randomUUID(),"Synthetic private portable message");assertThatThrownBy(()->care.export(other.id(),other.session(),id,0,0)).isInstanceOf(ForbiddenException.class);db.update("UPDATE user_sessions SET reauthenticated_at=CURRENT_TIMESTAMP WHERE id=?",learner.session());var page=care.export(learner.id(),learner.session(),id,0,0);assertThat(page.toString()).contains("Synthetic private portable message","reviewRequiredCategories","PROFESSIONAL_NOTES");}
}
